# 14c-3. Source pins. Behaviour alone cannot pin "this never reaches the model"
# — an LLM-backed classifier also returns a verdict — so the shape is pinned too.
#
# PARSED, NEVER GREPPED, and this module is the case that proves why: its
# docstring says in so many words "Never the LLM and never the network", and it
# imports from `geo_restriction`, which is itself one hop from the client
# factory. A substring scan for "get_llm_client" therefore fails in BOTH
# directions here — green when a module merely imports something that imports
# the client, red the moment a comment names the hazard. Reading Name/Attribute/
# import nodes answers the question the check is actually asking. (This is the
# same correction `skills_shortlist`'s pin records, arriving before the defect
# rather than after it.)
import ast as _gh_ast  # noqa: E402
import inspect as _gh_inspect  # noqa: E402

_GH_SRC = _gh_inspect.getsource(_ghost_mod)
_GH_TREE = _gh_ast.parse(_GH_SRC)
_GH_USED = (
    {n.id for n in _gh_ast.walk(_GH_TREE) if isinstance(n, _gh_ast.Name)}
    | {n.attr for n in _gh_ast.walk(_GH_TREE) if isinstance(n, _gh_ast.Attribute)}
    | {
        part
        for n in _gh_ast.walk(_GH_TREE)
        if isinstance(n, (_gh_ast.Import, _gh_ast.ImportFrom))
        for a in n.names
        # BOTH the bound name and every DOTTED SEGMENT of the module path. The
        # first draft collected `a.asname or a.name` only, so `import
        # urllib.request` contributed the single string "urllib.request" and the
        # forbidden-set intersection against "urllib" missed it entirely — the
        # check went GREEN with the network imported. Found by probing exactly
        # that defect in, per the rule at the top of check-mirrors.
        for part in {a.asname or a.name, *(a.name.split("."))}
    }
    | {
        part
        for n in _gh_ast.walk(_GH_TREE)
        if isinstance(n, _gh_ast.ImportFrom) and n.module
        for part in {n.module, *n.module.split(".")}
    }
)
check(
    "ghost: the classifier is source-pinned to no LLM, no network and no clock",
    len(_GH_SRC) > 2000
    and not _GH_USED & {
        "get_llm_client", "complete_json", "complete_text", "analyze_jd",
        "openai", "urllib", "requests", "httpx", "socket",
    }
    # `now` is a parameter — a `datetime.now()` here would make every check in
    # 14c depend on the hour it ran, and the thresholds unpinnable.
    and "datetime.now" not in _GH_SRC
    and "utcnow" not in _GH_SRC,
    f"{len(_GH_SRC)} chars, {len(_GH_USED)} identifiers",
)
# This is NOT an LLM task, so CLAUDE.md's "any new LLM task must add a stub
# branch and a smoke-test check" rule deliberately does not apply — and a future
# reader must not add one, because a stub branch here would mean the classifier
# had grown a model call the geo section's own rule forbids. Pinned the way the
# keyword-guard and skills-shortlist pins do it: by the absence of a routing token.
import app.llm.client as _gh_client_mod  # noqa: E402

_GH_CLIENT_SRC = _gh_inspect.getsource(_gh_client_mod)
check(
    "ghost: app/llm/client.py gained no stub branch for it — this is not an LLM task",
    "GHOST" not in _GH_CLIENT_SRC and "GHOST_SIGNAL" not in _GH_CLIENT_SRC,
)
# ONE parser for board dates, one answer. `job_search._posted_datetime` delegates
# here, so the ghost's age and the freshness tier can never disagree about the
# same string — the "one matcher, one answer" rule applied to a date. A second
# `fromisoformat` in `job_search` would let a posting be 93 days old to the badge
# and unparseable to the tier, on the same row.
import app.core.job_search as _gh_js_mod  # noqa: E402
from datetime import timezone as _gh_tz  # noqa: E402

from app.core.job_search import utc_now as _gh_utc_now  # noqa: E402
_GH_JS_SRC = _gh_inspect.getsource(_gh_js_mod)
_GH_ARGLESS_NOW = [
    _n.lineno
    for _n in _gh_ast.walk(_gh_ast.parse(_GH_JS_SRC))
    if isinstance(_n, _gh_ast.Call)
    and isinstance(_n.func, _gh_ast.Attribute)
    and _n.func.attr == "now"
    and not _n.args
    and not _n.keywords
]
check(
    "ghost: parse_board_date is THE board-date parser, and job_search delegates to it",
    _gh_parse_date("") is None and _gh_parse_date("junk") is None
    and _gh_parse_date(None) is None  # type: ignore[arg-type]
    and _gh_js_mod._posted_datetime("2026-06-02T03:17:15-04:00")
    == _gh_parse_date("2026-06-02T03:17:15-04:00")
    and "fromisoformat" not in _GH_JS_SRC,
)
# A BOARD DATE IS CONVERTED TO UTC, NEVER JUST STRIPPED OF ITS OFFSET.
# This assertion used to read `== _gh_dt(2026, 6, 2, 3, 17, 15)` — it PINNED the
# defect. Discarding `-04:00` reads 03:17 as UTC when it is 07:17, so a
# Greenhouse posting looked four hours younger than it was, and a UTC+13 board
# thirteen hours older. Day granularity does not make that safe: it decides
# which side of a day boundary `long_open` lands on. Both directions are pinned
# because "convert" is trivially satisfiable in one of them by adding a constant.
check(
    "ghost: a board date is CONVERTED to UTC, both directions — dropping the offset "
    "made a -04:00 posting 4h younger and a +13:00 one 13h older than it is",
    _gh_parse_date("2026-06-02T03:17:15-04:00") == _gh_dt(2026, 6, 2, 7, 17, 15)
    and _gh_parse_date("2026-06-02T03:17:15+13:00") == _gh_dt(2026, 6, 1, 14, 17, 15)
    # A naive string is already ours (the DateTime columns read back naive UTC)
    # and must pass through untouched, or every stored date shifts by the
    # machine's offset the moment this function is asked to be clever.
    and _gh_parse_date("2026-06-02T03:17:15") == _gh_dt(2026, 6, 2, 3, 17, 15),
    f'-04:00 -> {_gh_parse_date("2026-06-02T03:17:15-04:00")}',
)
# A DAY IS NOT A MIDNIGHT (2026-09-21). LinkedIn's card date is "2026-09-20", a
# whole day, and it was compared as that day's midnight against a to-the-minute
# cutoff: at 06:43 a 1-day alert called every posting LinkedIn had just returned
# for the last 24 hours "older posting — yesterday". `board_date_is_day` reads
# the SAME parse as `parse_board_date`, and decides by GRAMMAR: an explicit
# "T00:00" is a board's real midnight timestamp, an instant, and a value test
# (`time() == 0`) would have turned it into a whole day. The ghost age is
# untouched — the same string still parses to the same midnight.
check(
    "board dates: a date-only string names a whole DAY, by grammar — an explicit T00:00 stays an instant",
    _gh_is_day("2026-09-20") is True and _gh_is_day("20260920") is True
    and _gh_is_day("2026-09-20T00:00") is False
    and _gh_is_day("2026-09-20T16:25:30Z") is False
    and _gh_is_day("2026-09-20T16:25:30-04:00") is False
    and _gh_is_day("") is False and _gh_is_day("junk") is False
    and _gh_is_day(None) is False  # type: ignore[arg-type]
    and _gh_parse_date("2026-09-20") == _gh_dt(2026, 9, 20),
    f'day={_gh_is_day("2026-09-20")} T00:00={_gh_is_day("2026-09-20T00:00")}',
)
# THE CHIP PRINTS THE EARLIEST BOARD-STATED DATE WE HOLD. The reported case:
# Pentera's role carried a board date of 2026-09-07 on one LinkedIn listing
# (…4464364580, remembered in `posting_sightings.first_posted_at`) and
# 2026-09-20 on the one emailed (…4462220726) — a relist or a second opening,
# which nothing can tell apart; the email printed 2026-09-20.
# `earliest_board_date` is the minimum, as INSTANTS, over the card, Greenhouse's `first_published` and the sighting's
# `first_posted_at` — and NEVER `first_seen_at`, our own lower bound, which a
# first-seen-only twin pins below. The winner is returned VERBATIM (the card's
# own string object when nothing is earlier), so the Jobs card can tell
# "earlier" by string identity and TypeScript never compares dates. The card
# string is built at run time so `is` cannot pass on a shared literal constant.
_ebd_card = "-".join(["2026", "09", "20"])
_ebd_90 = _GH_NOW - _gh_td(days=90)
check(
    "earliest_board_date: a relist prints the role's EARLIEST board date, a lone card is itself, "
    "and our own first sighting is never a date",
    _gh_earliest("2026-09-20", {}, _GhSighting(
        first_posted_at="2026-09-07", first_url="https://il.linkedin.com/jobs/view/4464364580",
    )) == "2026-09-07"
    # Similarweb: nothing earlier known, so the card's own string comes back
    and _gh_earliest(_ebd_card, {}, None) is _ebd_card
    # a first_seen-only sighting (90 days) never becomes a printed date...
    and _gh_earliest("2026-09-20", {}, _GhSighting(first_seen_at=_ebd_90)) == "2026-09-20"
    # ...and with no card date either, the answer is unknown — never zero
    and _gh_earliest("", {}, _GhSighting(first_seen_at=_ebd_90)) == ""
    and _gh_earliest("", None, None) == ""
    # a card OLDER than the sighting wins
    and _gh_earliest("2026-09-01", {}, _GhSighting(first_posted_at="2026-09-07")) == "2026-09-01",
)
check(
    "earliest_board_date: instants, never strings — ties go to the card, verbatim; "
    "Greenhouse first_published counts; junk is ignored",
    # the same instant in two formats: the CARD's string, in both directions
    _gh_earliest("2026-09-20", {}, _GhSighting(first_posted_at="2026-09-20T00:00:00")) == "2026-09-20"
    and _gh_earliest("2026-09-20T00:00:00", {}, _GhSighting(first_posted_at="2026-09-20"))
    == "2026-09-20T00:00:00"
    # a mixed-offset pair a string `min` gets wrong: "…T04:30-05:00" is 09:30Z
    # and sorts BEFORE "…T05:00-04:00", which is 09:00Z and the earlier instant
    and _gh_earliest("2026-06-02T05:00:00-04:00", {},
                     _GhSighting(first_posted_at="2026-06-02T04:30:00-05:00"))
    == "2026-06-02T05:00:00-04:00"
    # Greenhouse: posted_at is updated_at; first_published is the listing's own
    and _gh_earliest("2026-09-02T10:00:00-04:00", {"first_published": "2026-01-01T09:00:00-05:00"}, None)
    == "2026-01-01T09:00:00-05:00"
    and _gh_earliest("2026-09-02", {"first_published": None}, None) == "2026-09-02"
    and _gh_earliest("2026-09-20", {}, _GhSighting(first_posted_at="junk")) == "2026-09-20",
)
# The new field is a PRINTED date and never an age: `long_open` keeps the two
# bases its unmeasured thresholds were tuned on. A 2020 first_posted_at on its
# own produces nothing at all.
_ebd_age = _gh(sighting=_GhSighting(first_posted_at="2020-01-01"))
check(
    "earliest_board_date: Sighting.first_posted_at never feeds long_open",
    _ebd_age is None,
    str(_ebd_age),
)
# ONE CLOCK, ONE FRAME. `record_sightings` writes `first_seen_at` as naive UTC
# and `search_jobs` measured ages against naive LOCAL time, so every `long_open`
# age was inflated by the machine's UTC offset — +3h in the primary market,
# which reported a share of postings a full day older than they were, always in
# the "older" direction. Pinned on the SOURCE too: a bare `datetime.now()` back
# in the search path reads as correct and is the whole bug.
check(
    "ghost: the search path measures age in UTC — a bare datetime.now() is naive LOCAL "
    "and silently ages every posting by the machine's offset",
    abs((_gh_utc_now() - _gh_dt.now(_gh_tz.utc).replace(tzinfo=None)).total_seconds()) < 5
    and _GH_ARGLESS_NOW == [],
    # Read off the AST, never the source text: this module's own docstrings say
    # "never `datetime.now()` inside" in prose, and a substring check reads the
    # promise as the violation. The same trap `resume_review`'s purity pin
    # documents one module over.
    f"argless datetime.now() at lines {_GH_ARGLESS_NOW}",
)
# THE IMPORTER CENSUS. A second call site would classify on a DIFFERENT gate and
# contradict the first about the same posting — the geo-restriction correction
# CLAUDE.md records as the one that mattered most (`kits.enqueue_kits` and
# `GET /jobs/history` each re-derived a verdict the search had already answered,
# and each disagreed with it). `kits.py`, `job_match.py`, `db/history.py` and
# `alerts.py` are where that would go today; the set is COMPUTED by walking every
# module the app ships, so it finds tomorrow's too.
#
# TWO tiers, because the module exports two different kinds of thing and only one
# of them is a gate. `db/sightings.py` legitimately imports the `Sighting`
# dataclass — it is the RETURN TYPE of `load_sightings`, a frozen value object
# that classifies nothing — while `detect_ghost_signals` is the classifier and
# must have exactly one importer. Folding the two would either forbid a type
# import the contract requires, or permit a second call site.
_GH_APP_DIR = _gh_Path(_ghost_mod.__file__).parents[1]  # …/app, never cwd
_GH_MOD_IMPORTERS: list[str] = []
_GH_FN_IMPORTERS: list[str] = []
_GH_SCANNED = 0
for _gh_py in sorted(_GH_APP_DIR.rglob("*.py")):
    _GH_SCANNED += 1
    _gh_rel = str(_gh_py.relative_to(_GH_APP_DIR)).replace("\\", "/")
    if _gh_rel == "core/ghost_signals.py":
        continue
    _gh_mod_hit = _gh_fn_hit = False
    for _gh_n in _gh_ast.walk(_gh_ast.parse(_gh_py.read_text(encoding="utf-8"))):
        if isinstance(_gh_n, _gh_ast.ImportFrom):
            if (_gh_n.module or "").split(".")[-1] == "ghost_signals":
                _gh_mod_hit = True
                _gh_fn_hit |= any(a.name == "detect_ghost_signals" for a in _gh_n.names)
            elif any(a.name == "ghost_signals" for a in _gh_n.names):
                _gh_mod_hit = True
        elif isinstance(_gh_n, _gh_ast.Import):
            _gh_mod_hit |= any(a.name.split(".")[-1] == "ghost_signals" for a in _gh_n.names)
    if _gh_mod_hit:
        _GH_MOD_IMPORTERS.append(_gh_rel)
    if _gh_fn_hit:
        _GH_FN_IMPORTERS.append(_gh_rel)
check(
    "ghost: exactly one CLASSIFIER call site in the whole app — core/job_search.py",
    _GH_FN_IMPORTERS == ["core/job_search.py"]
    and _GH_MOD_IMPORTERS == ["core/job_search.py", "db/sightings.py"]
    and _GH_SCANNED > 40,
    f"classifier={_GH_FN_IMPORTERS} module={_GH_MOD_IMPORTERS} ({_GH_SCANNED} modules scanned)",
)

# 14b-6. Prompt input bounds, output cap, and honest size errors.
# A production Sentry issue was a token-limit failure on a large master resume.
# Nothing in the backend bounded prompt input: the only ceiling was a 10 MB FILE
# cap, and a 10 MB PDF extracts to megabytes that went into the prompt whole.
import inspect as _lim_inspect  # noqa: E402

from app.core import jd_analyzer as _jd_analyzer_mod  # noqa: E402
from app.llm import client as _lim_client_mod  # noqa: E402
from app.parsers import structurer as _structure_resume_mod  # noqa: E402
from app.llm.limits import (  # noqa: E402
    ContextWindowExceeded,
    InputTooLarge,
    OutputTruncated,
    clip_utf8,
    require_within,
    utf8_bytes,
)

# BYTES, NOT CHARACTERS. Hebrew costs ~1.9 bytes/char, so a character cap
# silently grants the primary market roughly twice the tokens for the same
# number. Both halves in one check: the ratio must be real AND the cap must
# actually charge for it.
_HE = "ניהול מערכות"
check(
    "limits: sized in UTF-8 bytes, so Hebrew is not granted a bigger budget",
    utf8_bytes(_HE) > len(_HE) and utf8_bytes("systems management") == 18,
    f"he {len(_HE)} chars / {utf8_bytes(_HE)} bytes",
)

# A cap is a GUARD RAIL, not a budget: it must fire on the pathological input
# and never on a real CV. The false-positive half is the point — CLAUDE.md's
# rule is that a guard which also fires on legitimate input is worse than none.
_lim_real_cv = "Senior Engineer\n" + ("Built and shipped backend services. " * 1200)
check(
    "limits: a realistic long CV passes the cap, a pathological one does not",
    (require_within(_lim_real_cv, 256, "resume") is None)
    and utf8_bytes(_lim_real_cv) < 256 * 1024,
)
try:
    require_within("x" * (300 * 1024), 256, "resume")
    check("limits: an oversize resume raises InputTooLarge", False, "did not raise")
except InputTooLarge as _e:
    check(
        "limits: an oversize resume raises InputTooLarge carrying both numbers",
        _e.kind == "resume" and _e.size_kb == 300 and _e.cap_kb == 256,
        f"{_e.kind} {_e.size_kb}/{_e.cap_kb}",
    )

# clip_utf8 is for SCRAPED text only. It must cut on a character boundary (a raw
# byte slice mid-character yields U+FFFD) and back off to whitespace, because a
# shortened Hebrew word can BE a different real word (בנק -> נק) — a term the
# candidate never wrote, in the section the fabrication guard does not cover.
_lim_long_he = (_HE + " ") * 200
_lim_cut, _lim_flag = clip_utf8(_lim_long_he, 1)
check(
    "limits: clip cuts on a character boundary and never mid-word",
    _lim_flag is True
    and "�" not in _lim_cut
    and _lim_long_he.startswith(_lim_cut)
    and _lim_long_he[len(_lim_cut) : len(_lim_cut) + 1].isspace()
    and _lim_cut.split()[-1] in _HE.split(),
    f"{utf8_bytes(_lim_cut)} bytes, last word {_lim_cut.split()[-1]!r}",
)
check(
    "limits: text under the cap is returned untouched, and a word-less blob is not emptied",
    clip_utf8("short text", 256) == ("short text", False)
    and len(clip_utf8("A" * 5000, 1)[0]) == 1024,
)

# The classifier for a context overflow keys on `code`, never on the exception
# type: every malformed-parameter bug is also a BadRequestError, and reporting
# those as "your resume is too long" is a guard firing on legitimate input.
import httpx as _lim_httpx  # noqa: E402
from openai import BadRequestError as _LimBadRequest  # noqa: E402


def _lim_err(msg: str, code: str) -> _LimBadRequest:
    return _LimBadRequest(
        msg,
        response=_lim_httpx.Response(400, request=_lim_httpx.Request("POST", "http://x")),
        body={"code": code},
    )


check(
    "limits: only a context_length_exceeded 400 is treated as a size problem",
    _lim_client_mod._is_context_overflow(
        _lim_err("maximum context length is 128000 tokens", "context_length_exceeded")
    )
    is True
    and _lim_client_mod._is_context_overflow(
        _lim_err("Unsupported parameter: 'foo'", "unsupported_parameter")
    )
    is False,
)

# THE JSON TRUNCATION TRAP. chat.completions.create NEVER raises on
# finish_reason == "length" — it returns partial content, which json.loads then
# fails on, and the user is shown a parse error that reads as our bug. The
# SDK's own LengthFinishReasonError is reachable only via .parse()/.stream().
from types import SimpleNamespace as _LimNS  # noqa: E402

check(
    "limits: a truncated completion raises OutputTruncated instead of a parse error",
    _lim_client_mod._guard_finish_reason(
        _LimNS(choices=[_LimNS(finish_reason="stop")])
    )
    is None,
)
try:
    _lim_client_mod._guard_finish_reason(_LimNS(choices=[_LimNS(finish_reason="length")]))
    check("limits: finish_reason=length is detected", False, "did not raise")
except OutputTruncated:
    check("limits: finish_reason=length is detected", True)

# ...and it must be WIRED IN, not merely defined. Driving the real
# complete_json/complete_text is the only thing that catches the guard being
# deleted from the call path: a check that calls _guard_finish_reason directly
# still passes with the call site gone. Both entry points, because complete_text
# (the cover letter) has no parse step to fail loudly on its own — the letter
# would simply stop mid-sentence.
def _lim_truncating_metered(kwargs):
    return _LimNS(
        choices=[_LimNS(finish_reason="length", message=_LimNS(content='{"partial":'))]
    )


_lim_c_json = _lim_client_mod.OpenAIClient.__new__(_lim_client_mod.OpenAIClient)
_lim_c_json._model, _lim_c_json._unsupported, _lim_c_json._cap_param = "m", set(), "max_completion_tokens"
_lim_c_json._metered = _lim_truncating_metered
_lim_json_raised = ""
try:
    _lim_c_json.complete_json("sys", "user")
except OutputTruncated:
    _lim_json_raised = "typed"
except Exception as _e:  # noqa: BLE001 - a JSONDecodeError here is the defect
    _lim_json_raised = type(_e).__name__

_lim_c_text = _lim_client_mod.OpenAIClient.__new__(_lim_client_mod.OpenAIClient)
_lim_c_text._model, _lim_c_text._unsupported, _lim_c_text._cap_param = "m", set(), "max_completion_tokens"
_lim_c_text._metered = _lim_truncating_metered
_lim_text_raised = ""
try:
    _lim_c_text.complete_text("sys", "user")
except OutputTruncated:
    _lim_text_raised = "typed"
except Exception as _e:  # noqa: BLE001
    _lim_text_raised = type(_e).__name__

check(
    "limits: a truncated response raises through complete_json AND complete_text",
    _lim_json_raised == "typed" and _lim_text_raised == "typed",
    f"json={_lim_json_raised or 'no raise (JSONDecodeError would reach the user)'} "
    f"text={_lim_text_raised or 'no raise (letter silently cut short)'}",
)

# The output cap must actually reach the wire, and the capability probe must
# survive a model that rejects BOTH temperature and the modern cap name. The
# previous single-shot retry stripped exactly ONE kwarg, so such a call died on
# the second — which is what adding a second probe to it would have caused.
_lim_sent: list[dict] = []


def _lim_fake_metered(reject: tuple[str, ...]):
    def _run(kwargs):
        _lim_sent.append(dict(kwargs))
        for name in reject:
            if name in kwargs:
                raise _lim_err(f"Unsupported parameter: '{name}'", "unsupported_parameter")
        return _LimNS(
            choices=[_LimNS(finish_reason="stop", message=_LimNS(content='{"ok":1}'))]
        )

    return _run


_lim_c = _lim_client_mod.OpenAIClient.__new__(_lim_client_mod.OpenAIClient)
_lim_c._model, _lim_c._unsupported, _lim_c._cap_param = "m", set(), "max_completion_tokens"
_lim_c._metered = _lim_fake_metered(())
_lim_c.complete_json("sys", "user")
check(
    "limits: an explicit output cap is sent on every call",
    _lim_sent[-1].get("max_completion_tokens") == get_settings().llm_max_output_tokens,
    str(_lim_sent[-1].get("max_completion_tokens")),
)

_lim_sent.clear()
_lim_c2 = _lim_client_mod.OpenAIClient.__new__(_lim_client_mod.OpenAIClient)
_lim_c2._model, _lim_c2._unsupported, _lim_c2._cap_param = "m", set(), "max_completion_tokens"
_lim_c2._metered = _lim_fake_metered(("temperature", "max_completion_tokens"))
check(
    "limits: the probe survives a model rejecting temperature AND the cap name",
    _lim_c2.complete_json("sys", "user") == {"ok": 1}
    and _lim_c2._cap_param == "max_tokens"
    and "max_tokens" in _lim_sent[-1],
    f"attempts={len(_lim_sent)} final={sorted(k for k in _lim_sent[-1] if k not in ('model','messages','response_format'))}",
)

# A context overflow must NOT be mistaken for a capability problem and retried
# away — it has to surface as the typed error the route maps to 413.
_lim_c3 = _lim_client_mod.OpenAIClient.__new__(_lim_client_mod.OpenAIClient)
_lim_c3._model, _lim_c3._unsupported, _lim_c3._cap_param = "m", set(), "max_completion_tokens"


def _lim_ctx_metered(kwargs):
    raise _lim_err("maximum context length is 128000 tokens", "context_length_exceeded")


_lim_c3._metered = _lim_ctx_metered
try:
    _lim_c3.complete_json("sys", "user")
    check("limits: a context overflow surfaces as ContextWindowExceeded", False, "no raise")
except ContextWindowExceeded:
    check("limits: a context overflow surfaces as ContextWindowExceeded", True)

# The call sites that must refuse rather than truncate — the resume is the
# user's own document, and a silently shortened one is data loss they would
# discover from a recruiter.
# THE BOUNDARY PIN. Guarding the stored master resume is NOT enough: 25 request
# models take a `resume: ResumeModel` straight from the client body, so the
# stored row is one of twenty-six doors. Every model call builds its user
# message with a prompts.*_user builder, so that is where the bound lives — and
# every builder taking a guarded argument must actually carry the decorator, or
# it is a door standing open.
from app.llm import prompts as _lim_prompts  # noqa: E402

import re as _lim_re  # noqa: E402

_lim_src = _lim_inspect.getsource(_lim_prompts)
_lim_decorator = "@_bounded" + chr(10) + "def "
_lim_undecorated = [
    name
    for name, params in _lim_re.findall(r"^def (\w+_user)\(([^)]*)\)", _lim_src, _lim_re.M)
    if any(a in params for a in ("resume_json", "raw_text", "jd_text"))
    and (_lim_decorator + name + "(") not in _lim_src
]
check(
    "limits: every prompt builder taking a resume or JD argument is bounded",
    len(_lim_src) > 2000 and not _lim_undecorated,
    f"unbounded: {_lim_undecorated}" if _lim_undecorated else "all bounded",
)

_lim_big_resume = '{"x":"' + "y" * (300 * 1024) + '"}'
_lim_fired = []
for _lim_name, _lim_call in (
    ("cover_letter", lambda: _lim_prompts.cover_letter_user(_lim_big_resume, "{}", "warm")),
    ("jd_fit", lambda: _lim_prompts.jd_fit_user(_lim_big_resume, "jd")),
    ("interview_chat", lambda: _lim_prompts.interview_chat_user(_lim_big_resume, "jd", [])),
    ("linkedin", lambda: _lim_prompts.linkedin_user(_lim_big_resume)),
):
    try:
        _lim_call()
    except InputTooLarge:
        _lim_fired.append(_lim_name)
check(
    "limits: the bound reaches the routes that bypass the stored resume entirely",
    _lim_fired == ["cover_letter", "jd_fit", "interview_chat", "linkedin"],
    str(_lim_fired),
)
# The false-positive half, in the same block: an ordinary resume and job ad must
# sail through every one of them, or the guard is worse than no guard.
check(
    "limits: ordinary inputs are untouched by the bound",
    bool(_lim_prompts.jd_fit_user('{"name":"Jane"}', "We need a Python developer."))
    and bool(_lim_prompts.structure_resume_user("Jane Doe\nEngineer at Acme")),
)

check(
    "limits: structure_resume and analyze_jd guard their input before the model",
    "require_within" in _lim_inspect.getsource(_structure_resume_mod)
    and "require_within" in _lim_inspect.getsource(_jd_analyzer_mod),
)

# --- 14b-6 (P30-PASS-SIZE). Every builder parameter is MEASURED or NAMED ------------------------------------------
# Until this block the guard read three parameter names and skipped every value that was not a string, so five
# parameters on the session passes' builders reached the model unmeasured: the mock-interview transcript (a list,
# re-sent whole every turn, with no limit on turns or length), a question, a practice answer and the client-sent
# analysed JD (`jd_json`, also on the tailor's own builders) — beside the cover letter's `tone`. A multi-MB
# transcript went to OpenAI, and its context overflow then told the user their CV was too long. Every check below
# is DRIVEN through the builders, never grepped, and each catch sits beside its false-positive twin. The caps are
# read at call time, with the documented default as the fallback, so on a build without them the checks go red
# instead of aborting the suite.
_ps_s = get_settings()
_PS_ANS = getattr(_ps_s, "max_answer_kb", 16)
_PS_TR = getattr(_ps_s, "max_transcript_kb", 256)
_PS_JD = _ps_s.max_jd_kb
check(
    "P30-PASS-SIZE caps: an answer or a question 16 KB, a transcript 256 KB, a client-sent analysed JD 4 x the "
    "job-ad cap (derived from the analyser's always-on INPUT cap, never the output cap), and the scorecard the "
    "transcript cap plus two answers",
    getattr(_ps_s, "max_answer_kb", None) == 16
    and getattr(_ps_s, "max_transcript_kb", None) == 256
    and getattr(_ps_s, "max_jd_json_kb", None) == 4 * _PS_JD
    and getattr(_ps_s, "max_scorecard_transcript_kb", None) == 256 + 2 * 16,
    f"answer={getattr(_ps_s, 'max_answer_kb', None)} transcript={getattr(_ps_s, 'max_transcript_kb', None)} "
    f"jd_json={getattr(_ps_s, 'max_jd_json_kb', None)} scorecard={getattr(_ps_s, 'max_scorecard_transcript_kb', None)}",
)


def _ps_env(**values):  # noqa: ANN003
    """Set env vars and clear the settings cache; returns what to restore (section 29's _env29, needed earlier)."""
    previous = {k: os.environ.get(k) for k in values}
    for k, v in values.items():
        os.environ[k] = v
    get_settings.cache_clear()
    return previous


def _ps_restore(previous):  # noqa: ANN001
    for k, v in previous.items():
        if v is None:
            os.environ.pop(k, None)
        else:
            os.environ[k] = v
    get_settings.cache_clear()


def _ps_kind(call):  # noqa: ANN001
    """The kind a builder call is refused with, None when it is not refused, or 'raised <Type>' for anything else
    (so a build that crashes on a list reads as a failed check, never an aborted suite)."""
    try:
        call()
    except InputTooLarge as exc:
        return exc.kind
    except Exception as exc:  # noqa: BLE001
        return f"raised {type(exc).__name__}"
    return None


def _ps_fill(target_bytes, turns=()):  # noqa: ANN001
    """`turns`, then ONE interviewer turn padded so the transcript the model reads — `_format_transcript`, role
    prefixes and newlines included — is exactly `target_bytes` long."""
    head = list(turns) + [("interviewer", "")]
    base = utf8_bytes(_lim_prompts._format_transcript(head))
    return list(turns) + [("interviewer", "q" * (target_bytes - base))]


def _ps_chat(transcript):  # noqa: ANN001
    return _ps_kind(lambda: _lim_prompts.interview_chat_user('{"name":"Jane"}', "", transcript))


def _ps_card(transcript):  # noqa: ANN001
    return _ps_kind(lambda: _lim_prompts.interview_scorecard_user('{"name":"Jane"}', "", transcript))


# Ten answers of 15 KB: each under the per-answer cap, so only the TOTAL can refuse them.
_PS_CAND = [("candidate", "a" * (15 * 1024))] * 10
_ps_at = _ps_fill(_PS_TR * 1024, _PS_CAND)
_ps_over = _ps_fill(_PS_TR * 1024 + 1, _PS_CAND)
check(
    "P30-PASS-SIZE transcript: a chat transcript one byte over the cap, measured as the text the model reads, is "
    "refused as kind 'transcript' — and the same transcript exactly AT the cap is not",
    _ps_chat(_ps_over) == "transcript" and _ps_chat(_ps_at) is None,
    f"over={_ps_chat(_ps_over)} at={_ps_chat(_ps_at)}",
)
# The false-positive twin that sized the cap: the pass allows 60 calls, i.e. an opener and 59 answers, so an honest
# session can send 59 exchanges. Sized against the prompt's 6-8 question arc instead, 128 KB fired on this one.
_PS_HE_ANSWER = ("בתפקיד האחרון הובלתי את המעבר של מערכת התשלומים לענן, ועבדתי עם צוות של שישה מהנדסים. " * 20)[:900]
_PS_HE_TURN = ("תודה. שאלת המשך: ספרו לי על החלטה טכנית שקיבלתם ושהתבררה כשגויה, ומה עשיתם אחריה. " * 10)[:500]
_ps_full = [pair for _ in range(59) for pair in (("interviewer", _PS_HE_TURN), ("candidate", _PS_HE_ANSWER))]
_ps_full_kb = utf8_bytes(_lim_prompts._format_transcript(_ps_full)) / 1024
check(
    "P30-PASS-SIZE twin: a FULL-PASS honest Hebrew session — 59 exchanges of a 900-character answer and a "
    "500-character interviewer turn — passes both the chat and the scorecard builder",
    _ps_chat(_ps_full) is None and _ps_card(_ps_full) is None and 120 < _ps_full_kb < _PS_TR,
    f"{_ps_full_kb:.0f} KB against a {_PS_TR} KB cap",
)

# The scorecard reads one reply and one refused answer more than the chat ever accepted, so a session the chat has
# just refused can be scored whenever that reply and that answer each fit in max_answer_kb (the ordinary case; an
# interviewer reply has no per-turn cap). It is refused with its OWN kind: the chat's sentence says "end the session to
# get your scorecard", which would send someone whose scorecard was refused round in a loop.
_PS_SC = _PS_TR + 2 * _PS_ANS
_ps_sc_over = _ps_fill(_PS_SC * 1024 + 1, _PS_CAND)
_ps_sc_at = _ps_fill(_PS_SC * 1024, _PS_CAND)
_ps_sc_mid = _ps_fill((_PS_TR + 1) * 1024, _PS_CAND)
check(
    "P30-PASS-SIZE scorecard: one byte over the transcript cap plus two answers is refused as kind 'session' "
    "(never 'transcript'), exactly at it passes, and the transcript cap + 1 KB fails the CHAT but passes the "
    "scorecard — the stranded-session case",
    _ps_card(_ps_sc_over) == "session" and _ps_card(_ps_sc_at) is None
    and _ps_chat(_ps_sc_mid) == "transcript" and _ps_card(_ps_sc_mid) is None,
    f"over={_ps_card(_ps_sc_over)} at={_ps_card(_ps_sc_at)} mid chat={_ps_chat(_ps_sc_mid)} card={_ps_card(_ps_sc_mid)}",
)
_ps_prev = _ps_env(MAX_TRANSCRIPT_KB="0")
try:
    _ps_mb = _ps_fill(1024 * 1024, _PS_CAND)
    _ps_off = (_ps_chat(_ps_mb), _ps_card(_ps_mb))
finally:
    _ps_restore(_ps_prev)
check(
    "P30-PASS-SIZE kill switch: MAX_TRANSCRIPT_KB=0 lets a 1 MB transcript through BOTH builders — the scorecard's "
    "derived allowance switches off with the chat cap, and never turns into a 32 KB cap of its own",
    _ps_off == (None, None) and getattr(get_settings(), "max_transcript_kb", 256) == _PS_TR,
    str(_ps_off),
)

# Each CANDIDATE turn is the user's own answer and gets its own cap and sentence ("shorten it"), because the client
# hands a refused answer back to the draft. An INTERVIEWER turn is model text: telling the user to shorten it would
# be false, so it counts toward the total only. The scorecard does not re-check each turn — nothing on it can be
# edited, so a per-turn refusal there could only strand a session an old tab kept a long answer in.
_ps_17 = "a" * (17 * 1024)
_ps_he3k = ("ניהלתי צוות של חמישה מהנדסים ובניתי את תשתית הנתונים מאפס. " * 60)[:1700]
_ps_t3_cand = [("interviewer", "Tell me about a project."), ("candidate", _ps_17), ("interviewer", "q" * 3000)]
_ps_t3_int = [("interviewer", _ps_17), ("candidate", "It went well."), ("interviewer", "q" * 3000)]
_ps_t3_he = [("interviewer", "Tell me about a project."), ("candidate", _ps_he3k)]
check(
    "P30-PASS-SIZE per answer: one 17 KB CANDIDATE turn in a ~20 KB transcript is refused as kind 'answer'; the "
    "same 17 KB as an INTERVIEWER turn is not; a 3 KB Hebrew answer passes; and the scorecard does not re-check "
    "each turn",
    _ps_chat(_ps_t3_cand) == "answer" and _ps_chat(_ps_t3_int) is None and _ps_chat(_ps_t3_he) is None
    and _ps_card(_ps_t3_cand) is None and utf8_bytes(_ps_he3k) > 2 * 1024,
    f"cand={_ps_chat(_ps_t3_cand)} int={_ps_chat(_ps_t3_int)} he={_ps_chat(_ps_t3_he)} card={_ps_card(_ps_t3_cand)}",
)
# The role string is part of what the model reads (`ROLE: text`), so it is measured with it. (The route also takes
# the role as a two-value Literal, pinned over HTTP in section 32.)
check(
    "P30-PASS-SIZE the role counts: a transcript whose ROLE strings alone carry it past the cap is refused, "
    "because the guard measures the formatted text, not the answers",
    _ps_chat([("x" * (_PS_TR * 1024), "hi")]) == "transcript",
    str(_ps_chat([("x" * (_PS_TR * 1024), "hi")])),
)

# A question and a practice answer. A refused QUESTION gets its own kind: telling someone to shorten "the answer"
# when it was the question that was too long is the false-sentence defect this whole change exists to remove.
_ps_q_he = ("מה הייתה ההחלטה הטכנית הקשה ביותר שקיבלתם, ולמה? " * 20)[:500]  # the extension clips at 500 characters
_ps_16 = "b" * (_PS_ANS * 1024)
_ps_t4 = {
    "feedback(answer)": _ps_kind(lambda: _lim_prompts.interview_feedback_user("{}", "Why us?", _ps_17)),
    "feedback(question)": _ps_kind(lambda: _lim_prompts.interview_feedback_user("{}", _ps_17, "Because.")),
    "answer(question)": _ps_kind(lambda: _lim_prompts.interview_answer_user("{}", "{}", _ps_17)),
    "screening(question)": _ps_kind(lambda: _lim_prompts.screening_user("{}", "", _ps_17)),
}
_ps_t4_ok = {
    "screening(500-char Hebrew question)": _ps_kind(lambda: _lim_prompts.screening_user("{}", "", _ps_q_he)),
    "answer(500-char Hebrew question)": _ps_kind(lambda: _lim_prompts.interview_answer_user("{}", "{}", _ps_q_he)),
    "feedback(3 KB Hebrew answer)": _ps_kind(lambda: _lim_prompts.interview_feedback_user("{}", _ps_q_he, _ps_he3k)),
    "feedback(answer exactly at the cap)": _ps_kind(lambda: _lim_prompts.interview_feedback_user("{}", "Q", _ps_16)),
}
check(
    "P30-PASS-SIZE question/answer: a 17 KB practice answer is refused as 'answer', and a 17 KB question on the "
    "feedback, model-answer and screening builders as 'question', never 'answer'",
    _ps_t4 == {
        "feedback(answer)": "answer", "feedback(question)": "question",
        "answer(question)": "question", "screening(question)": "question",
    },
    str(_ps_t4),
)
check(
    "P30-PASS-SIZE twin: the extension's 500-character Hebrew question, a 3 KB Hebrew practice answer and an answer "
    "exactly at the cap all pass",
    all(v is None for v in _ps_t4_ok.values()),
    str(_ps_t4_ok),
)

# The client-sent analysed JD. Its cap is DERIVED from the analyser's input cap (4 x max_jd_kb): an analysed JD is
# model output read from at most max_jd_kb of text. Not from llm_max_output_tokens, which can be 0 (off) or dropped
# by the capability probe. The twin is HAND-BUILT, because the stub analyser returns a small canned JD whatever it
# reads: the largest ad the analyser accepts, copied WHOLE into three lists, which a real analysis never reaches.
from app.models import JDModel as _PS_JDModel  # noqa: E402

_PS_HE_SENT = "אחריות על תכנון, פיתוח ותחזוקה של שירותי צד שרת בסביבת ענן מבוזרת, כולל ניטור וזמינות גבוהה."
_ps_sents: list[str] = []
while utf8_bytes("\n".join(_ps_sents + [f"{len(_ps_sents)}. {_PS_HE_SENT}"])) <= _PS_JD * 1024:
    _ps_sents.append(f"{len(_ps_sents)}. {_PS_HE_SENT}")
_PS_MAX_JD = _PS_JDModel(
    job_title="מהנדס/ת תוכנה בכיר/ה", company="חברת תשתיות ענן", seniority="senior", language="he", market="IL",
    hard_skills=["Python", "Kubernetes", "PostgreSQL", "Kafka"], soft_skills=["עבודת צוות", "תקשורת"],
    responsibilities=list(_ps_sents), qualifications=list(_ps_sents), keywords=list(_ps_sents),
)
_ps_max_jd_json = _PS_MAX_JD.model_dump_json()
_ps_max_jd_kb = utf8_bytes(_ps_max_jd_json) / 1024
_ps_big_jd_json = _PS_JDModel(responsibilities=["x" * (4 * _PS_JD * 1024)]).model_dump_json()
_PS_JD_BUILDERS = {
    "cover_letter": lambda j: _lim_prompts.cover_letter_user("{}", j, "warm"),
    "interview_questions": lambda j: _lim_prompts.interview_questions_user("{}", j),
    "interview_answer": lambda j: _lim_prompts.interview_answer_user("{}", j, "Why us?"),
    "fit_score": lambda j: _lim_prompts.fit_score_user("{}", j),
    "plan_cv": lambda j: _lim_prompts.plan_cv_user("{}", j),
    "tailor": lambda j: _lim_prompts.tailor_user("{}", j),
}
_ps_jd_over = {n: _ps_kind(lambda b=b: b(_ps_big_jd_json)) for n, b in _PS_JD_BUILDERS.items()}
_ps_jd_max = {n: _ps_kind(lambda b=b: b(_ps_max_jd_json)) for n, b in _PS_JD_BUILDERS.items()}
check(
    "P30-PASS-SIZE jd_json: an analysed JD over 4 x the job-ad cap is refused as kind 'jd' by all six builders "
    "that take one (cover letter, interview questions and answer, fit score, plan, tailor)",
    set(_ps_jd_over.values()) == {"jd"},
    str(_ps_jd_over),
)
check(
    "P30-PASS-SIZE twin: a hand-built maximal Hebrew JD — the largest ad the analyser accepts, copied whole into "
    "responsibilities, qualifications AND keywords — passes all six",
    all(v is None for v in _ps_jd_max.values()) and 90 < _ps_max_jd_kb < 4 * _PS_JD
    and _ps_kind(lambda: _lim_prompts.analyze_jd_user("\n".join(_ps_sents))) is None,
    f"{_ps_max_jd_kb:.0f} KB: {_ps_jd_max}",
)
_ps_prev = _ps_env(LLM_MAX_OUTPUT_TOKENS="0")
try:
    _ps_jd_nocap = _ps_kind(lambda: _lim_prompts.fit_score_user("{}", _ps_big_jd_json))
finally:
    _ps_restore(_ps_prev)
_ps_prev = _ps_env(MAX_JD_KB="0")
try:
    _ps_jd_off = (
        _ps_kind(lambda: _lim_prompts.fit_score_user("{}", _ps_big_jd_json)),
        _ps_kind(lambda: _lim_prompts.analyze_jd_user("x" * (40 * 1024))),
    )
finally:
    _ps_restore(_ps_prev)
check(
    "P30-PASS-SIZE kill switches: with LLM_MAX_OUTPUT_TOKENS=0 the jd_json cap still holds (it does not ride on the "
    "output cap), and MAX_JD_KB=0 switches BOTH job-ad checks off together",
    _ps_jd_nocap == "jd" and _ps_jd_off == (None, None) and get_settings().max_jd_kb == _PS_JD,
    f"no output cap: {_ps_jd_nocap}; MAX_JD_KB=0: {_ps_jd_off}",
)

# THE PIN, INVERTED. The old pin (above) looked for three names; a parameter called anything else passed it green.
# This one walks EVERY module-level `*_user` builder, decorated or not, and every parameter must be measured by the
# rule table or named on `_UNMEASURED` — keyed by (builder, parameter), so allowing `company` for one builder can
# never quietly cover the next builder that takes a user-typed `company` — with a reason of a known category. A
# builder that measures anything must carry the `__bounded__` marker (read off the function, never the source
# text), and one without it must be named on `_UNDECORATED`. Stale entries are red too.
_PS_CATEGORIES = ("server", "schema", "clipped", "third-party", "known open")


def _ps_unclassified(mod):  # noqa: ANN001
    """What the prompt module leaves unaccounted for, as sentences; [] when every parameter is."""
    tables = {n: getattr(mod, n, None) for n in ("_MEASURED", "_MEASURED_IN", "_UNMEASURED", "_UNDECORATED")}
    missing = [n for n, t in tables.items() if not (isinstance(t, dict) and t)]
    if missing:
        return [f"prompts.py has no {', '.join(missing)} table(s)"]
    measured, measured_in, unmeasured, undecorated = tables.values()
    out: list[str] = []
    builders = {n: f for n, f in vars(mod).items() if n.endswith("_user") and _lim_inspect.isfunction(f)}
    if len(builders) < 20:
        out.append(f"only {len(builders)} *_user builders were found (expected at least 20) — the walk broke")
    settings = get_settings()
    for rule in [*measured.values(), *measured_in.values()]:
        for attr in (rule.cap, rule.turn_cap):
            if attr and not isinstance(getattr(settings, attr, None), int):
                out.append(f"a rule reads settings.{attr}, which is not an int setting")
    params: dict[str, list[str]] = {}
    for name, fn in sorted(builders.items()):
        params[name] = list(_lim_inspect.signature(fn).parameters)
        marked = getattr(fn, "__bounded__", False) is True
        measures = [p for p in params[name] if (name, p) in measured_in or p in measured]
        for p in params[name]:
            if p in measures:
                continue
            reason = unmeasured.get((name, p))
            if not (isinstance(reason, str) and reason.split(":")[0] in _PS_CATEGORIES and len(reason) > 25):
                out.append(f"{name}({p}) is neither measured nor on _UNMEASURED with a categorised reason")
        if measures and not marked:
            out.append(f"{name} measures {measures} but is not @_bounded")
        if not marked and not (isinstance(undecorated.get(name), str) and undecorated.get(name)):
            out.append(f"{name} is not @_bounded and _UNDECORATED does not name it")
        if marked and name in undecorated:
            out.append(f"{name} is @_bounded but still named on _UNDECORATED")
    for builder, param in [*unmeasured, *measured_in]:
        if param not in params.get(builder, []):
            out.append(f"({builder}, {param}) names a builder parameter that does not exist")
    for builder in undecorated:
        if builder not in builders:
            out.append(f"_UNDECORATED names {builder}, which does not exist")
    return out


_ps_real = _ps_unclassified(_lim_prompts)


def x_probe_user(resume_json: str, transcript: list[tuple[str, str]]) -> str:  # an undecorated builder
    return f"{resume_json}{transcript}"


def _ps_probe_b(resume_json: str, extra_notes: str) -> str:
    return f"{resume_json}{extra_notes}"


_ps_probe_b.__name__ = "y_probe_user"
_ps_probes: dict[str, list[str]] = {}
try:
    setattr(_lim_prompts, "x_probe_user", x_probe_user)
    _ps_probes["undecorated"] = _ps_unclassified(_lim_prompts)
    delattr(_lim_prompts, "x_probe_user")
    _ps_bounded = getattr(_lim_prompts, "_bounded")
    setattr(_lim_prompts, "y_probe_user", _ps_bounded(_ps_probe_b))
    _ps_probes["unclassified"] = _ps_unclassified(_lim_prompts)
finally:
    for _ps_n in ("x_probe_user", "y_probe_user"):
        if hasattr(_lim_prompts, _ps_n):
            delattr(_lim_prompts, _ps_n)
_ps_probes["restored"] = _ps_unclassified(_lim_prompts)
check(
    "P30-PASS-SIZE the inverted pin: every parameter of every *_user builder in prompts.py, decorated or not, is "
    "measured or named on _UNMEASURED with a categorised reason, and every builder that measures one is @_bounded",
    _ps_real == [],
    "; ".join(_ps_real) or f"{sum(1 for n in vars(_lim_prompts) if n.endswith('_user'))} builders accounted for",
)
check(
    "P30-PASS-SIZE the pin probed both ways: an undecorated builder taking `transcript` is red, a decorated builder "
    "with an unclassified parameter is red, and both removed it is green again",
    any("x_probe_user" in p for p in _ps_probes.get("undecorated", []))
    and any("y_probe_user(extra_notes)" in p for p in _ps_probes.get("unclassified", []))
    and _ps_probes.get("restored") == _ps_real == [],
    str({k: [p for p in v if "probe" in p] for k, v in _ps_probes.items()}),
)
# The non-string skip is gone for every measured name: a value it cannot measure is a loud TypeError, never a
# parameter that silently goes unmeasured (which is how the transcript list slipped through).
check(
    "P30-PASS-SIZE a measured parameter the guard cannot measure raises instead of being skipped",
    _ps_kind(lambda: _lim_prompts.interview_feedback_user("{}", "Q", ["not", "a", "string"])) == "raised TypeError",
    str(_ps_kind(lambda: _lim_prompts.interview_feedback_user("{}", "Q", ["not", "a", "string"]))),
)

