        # --- 32.20 The cover-letter pass (OD-2 b): a posting's first letter, and its changes -------------------------
        _CL_BODY32 = {"resume": _R32, "jd": _JDJ32}
        _CL_OTHER32 = {"resume": _R32, "jd": dict(_JDJ32, company="Beta Labs")}
        _cl_ref32 = _ref_of32(_JDJ32)
