        _cl_limit32 = _snap32(_cl_uid32).limit
        _cl_first32 = _c32c.post("/cover-letter", json=dict(_CL_BODY32, tone="professional"), headers=_CL32_H)
        _cl_first_at32 = _q32.utc_now()
